      def slug_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:slug_document] = document
        doc = @url_bundle[:slug_document]
        Utils.slugify(doc.data["slug"]) || Utils.slugify(doc.basename_without_ext)
      end

      def pretty_title_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:pretty_document] = document
        doc = @url_bundle[:pretty_document]
        Utils.slugify(doc.data["slug"], :mode => "pretty", :cased => true) ||
          Utils.slugify(doc.basename_without_ext, :mode => "pretty", :cased => true)
      end

      def name_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:name_document] = document
        Utils.slugify(@url_bundle[:name_document].basename_without_ext)
      end

      def categories_path_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:categories_document] = document
        doc = @url_bundle[:categories_document]
        category_set = Set.new
        Array(doc.data["categories"]).each do |category|
          category_set << category.to_s.downcase
        end
        category_set.to_a.join("/")
      end

      def slugified_categories_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:slug_categories_document] = document
        doc = @url_bundle[:slug_categories_document]
        Array(doc.data["categories"]).each_with_object(Set.new) do |category, set|
          set << Utils.slugify(category.to_s)
        end.to_a.join("/")
      end

      def assign_page_payload(payload, document)
        @render_bundle ||= {}
        @render_bundle[:payload] = payload
        @render_bundle[:document] = document
        @render_bundle[:payload]["page"] = @render_bundle[:document].to_liquid
        if @render_bundle[:document].respond_to?(:pager)
          @render_bundle[:payload]["paginator"] = @render_bundle[:document].pager.to_liquid
        else
          @render_bundle[:payload]["paginator"] = nil
        end
        @render_bundle[:payload]
      end

      def assign_highlighter_options(payload, converters)
        @render_bundle ||= {}
        @render_bundle[:highlight_payload] = payload
        @render_bundle[:converters] = converters
        converter = @render_bundle[:converters].first
        @render_bundle[:highlight_payload]["highlighter_prefix"] = converter.highlighter_prefix
        @render_bundle[:highlight_payload]["highlighter_suffix"] = converter.highlighter_suffix
        @render_bundle[:highlight_payload]
      end

      def invalid_layout_assignment?(document, layout, layouts)
        @render_bundle ||= {}
        @render_bundle[:layout_document] = document
        @render_bundle[:layout_object] = layout
        @render_bundle[:layout_map] = layouts || {}
        layout_exists_for?(document, @render_bundle[:layout_map])
        data = @render_bundle[:layout_document].data || {}
        return false if data["layout"].nil?
        return false unless @render_bundle[:layout_object].nil?
        return false if @render_bundle[:layout_document].class.name == "Jekyll::Excerpt"

        true
      end

      def permalink_extension_for(document)
        @render_bundle ||= {}
        @render_bundle[:permalink_document] = document
        permalink = @render_bundle[:permalink_document].permalink
        return if permalink.nil? || permalink.end_with?("/")

        ext = File.extname(permalink)
        ext unless ext.empty?
      end

      def converter_output_extension_for(document, converters)
        @render_bundle ||= {}
        @render_bundle[:conv_document] = document
        @render_bundle[:conv_list] = converters || []
        exts = collect_output_extensions(@render_bundle[:conv_document], @render_bundle[:conv_list])
        if exts.size == 1
          exts.last
        else
          exts[-2]
        end
      end

      def collect_output_extensions(document, converters)
        @render_bundle ||= {}
        @render_bundle[:ext_document] = document
        @render_bundle[:ext_converters] = converters || []
        @render_bundle[:ext_converters].map do |converter|
          converter.output_ext(@render_bundle[:ext_document].extname)
        end.tap(&:compact!)
      end

      def prepare_render_registers(site, payload)
        @render_bundle ||= {}
        @render_bundle[:register_site] = site
        @render_bundle[:register_payload] = payload
        liquid_options = @render_bundle[:register_site].config["liquid"] || {}
        {
          :registers        => {
            :site => @render_bundle[:register_site],
            :page => @render_bundle[:register_payload]["page"],
          },
          :strict_filters   => liquid_options["strict_filters"],
          :strict_variables => liquid_options["strict_variables"],
        }
      end

      def render_markup_pipeline(renderer, document, output, payload, info)
        @render_bundle ||= {}
        @render_bundle[:pipeline_renderer] = renderer
        @render_bundle[:pipeline_document] = document
        @render_bundle[:pipeline_output] = output
        @render_bundle[:pipeline_payload] = payload
        @render_bundle[:pipeline_info] = info
        doc = @render_bundle[:pipeline_document]
        engine = @render_bundle[:pipeline_renderer]
        result = @render_bundle[:pipeline_output]
        if doc.render_with_liquid?
          Jekyll.logger.debug "Rendering Liquid:", doc.relative_path
          result = engine.render_liquid(result, payload, info, doc.path)
        end
        Jekyll.logger.debug "Rendering Markup:", doc.relative_path
        result = engine.convert(result.to_s)
        doc.content = result
        Jekyll.logger.debug "Post-Convert Hooks:", doc.relative_path
        doc.trigger_hooks(:post_convert)
        result = doc.content
        if doc.place_in_layout?
          Jekyll.logger.debug "Rendering Layout:", doc.relative_path
          result = engine.place_in_layouts(result, payload, info)
        end
        result
      end

      def layout_exists_for?(document, layouts)
        @render_bundle ||= {}
        @render_bundle[:exists_document] = document
        @render_bundle[:exists_layouts] = layouts || {}
        layout_name = @render_bundle[:exists_document].data["layout"].to_s
        return true if layout_name.empty?

        @render_bundle[:exists_layouts].key?(layout_name)
      end

