      def print_excerpt_warning(relative_path, separator)
        @excerpt_bundle ||= {}
        @excerpt_bundle[:warn_path] = relative_path
        @excerpt_bundle[:warn_separator] = separator
        Jekyll.logger.warn "Warning:", "Excerpt modified in #{@excerpt_bundle[:warn_path]}!"
        Jekyll.logger.warn "", "Found a Liquid block containing the excerpt separator" \
                           " #{@excerpt_bundle[:warn_separator].inspect}. "
        Jekyll.logger.warn "", "The block has been modified with the appropriate closing tag."
        Jekyll.logger.warn "", "Feel free to define a custom excerpt or excerpt_separator in the"
        Jekyll.logger.warn "", "document's Front Matter if the generated excerpt is unsatisfactory."
      end

      def excerpt_liquid_renderable?(content, data, extname)
        @excerpt_bundle ||= {}
        @excerpt_bundle[:render_content] = content
        @excerpt_bundle[:render_data] = data || {}
        @excerpt_bundle[:render_ext] = extname
        return false if @excerpt_bundle[:render_data]["render_with_liquid"] == false
        return false if yaml_document?(@excerpt_bundle[:render_ext])
        return false if coffeescript_document?(@excerpt_bundle[:render_ext])

        Utils.has_liquid_construct?(@excerpt_bundle[:render_content])
      end

      def read_document_body(document, opts)
        @output_bundle ||= {}
        @output_bundle[:document] = document
        @output_bundle[:opts] = opts || {}
        doc = @output_bundle[:document]
        Jekyll.logger.debug "Reading:", doc.relative_path
        if yaml_document?(doc.extname)
          ivar_name = "data"
          doc.instance_variable_set("@" + ivar_name, SafeYAML.load_file(doc.path))
        else
          begin
            merge_default_data(doc)
            ingest_file_content(doc, @output_bundle[:opts])
            complete_post_data(doc)
          rescue StandardError => e
            handle_read_failure(doc, e)
          end
        end
      end

      def merge_default_data(document)
        @output_bundle ||= {}
        @output_bundle[:defaults_document] = document
        doc = @output_bundle[:defaults_document]
        defaults = doc.site.frontmatter_defaults.all(doc.relative_path, doc.type)
        unless defaults.empty?
          merge_front_matter!(doc, defaults, "front matter defaults")
        end
      end

      def ingest_file_content(document, opts)
        @output_bundle ||= {}
        @output_bundle[:ingest_document] = document
        @output_bundle[:ingest_opts] = opts || {}
        doc = @output_bundle[:ingest_document]
        merged_opts = Utils.merged_file_read_opts(doc.site, @output_bundle[:ingest_opts])
        doc.content = File.read(doc.path, **merged_opts)
        if doc.content =~ Document::YAML_FRONT_MATTER_REGEXP
          doc.content = Regexp.last_match.post_match
          data_file = SafeYAML.load(Regexp.last_match(1))
          merge_front_matter!(doc, data_file, "YAML front matter") if data_file
        end
      end

      def handle_read_failure(document, error)
        @output_bundle ||= {}
        @output_bundle[:error_document] = document
        @output_bundle[:error] = error
        doc = @output_bundle[:error_document]
        if @output_bundle[:error].is_a?(Psych::SyntaxError)
          Jekyll.logger.error "Error:", "YAML Exception reading #{doc.path}: #{@output_bundle[:error].message}"
        else
          Jekyll.logger.error "Error:", "could not read file #{doc.path}: #{@output_bundle[:error].message}"
        end

        if doc.site.config["strict_front_matter"] || @output_bundle[:error].is_a?(Jekyll::Errors::FatalException)
          raise @output_bundle[:error]
        end
      end

      def yaml_document?(extname)
        @output_bundle ||= {}
        @output_bundle[:yaml_ext] = extname
        YAML_FILE_EXTS.include?(@output_bundle[:yaml_ext])
      end

      def sass_document?(extname)
        @output_bundle ||= {}
        @output_bundle[:sass_ext] = extname
        SASS_FILE_EXTS.include?(@output_bundle[:sass_ext])
      end

      def coffeescript_document?(extname)
        @output_bundle ||= {}
        @output_bundle[:coffee_ext] = extname
        @output_bundle[:coffee_ext] == ".coffee"
      end

      def asset_document?(extname)
        @output_bundle ||= {}
        @output_bundle[:asset_ext] = extname
        sass_document?(@output_bundle[:asset_ext]) || coffeescript_document?(@output_bundle[:asset_ext])
      end

      def liquid_render_allowed?(data, content, extname)
        @output_bundle ||= {}
        @output_bundle[:liquid_data] = data || {}
        @output_bundle[:liquid_content] = content
        @output_bundle[:liquid_ext] = extname
        return false if @output_bundle[:liquid_data]["render_with_liquid"] == false
        return false if coffeescript_document?(@output_bundle[:liquid_ext])
        return false if yaml_document?(@output_bundle[:liquid_ext])

        Utils.has_liquid_construct?(@output_bundle[:liquid_content])
      end

      def layout_skipped?(data)
        @output_bundle ||= {}
        @output_bundle[:layout_data] = data || {}
        @output_bundle[:layout_data]["layout"] == "none"
      end

      def layout_placement_allowed?(data, extname)
        @output_bundle ||= {}
        @output_bundle[:place_data] = data || {}
        @output_bundle[:place_ext] = extname
        return false if asset_document?(@output_bundle[:place_ext])
        return false if yaml_document?(@output_bundle[:place_ext])
        return false if layout_skipped?(@output_bundle[:place_data])

        true
      end

      def compose_write!(dest, path, output)
        @output_bundle ||= {}
        @output_bundle[:write_dest] = dest
        @output_bundle[:write_path] = path
        @output_bundle[:write_output] = output
        FileUtils.mkdir_p(File.dirname(@output_bundle[:write_path]))
        Jekyll.logger.debug "Writing:", @output_bundle[:write_path]
        File.write(@output_bundle[:write_path], @output_bundle[:write_output], :mode => "wb")
        @output_bundle[:write_path]
      end

      def publication_allowed?(data)
        @output_bundle ||= {}
        @output_bundle[:publish_data] = data || {}
        !(@output_bundle[:publish_data].key?("published") && @output_bundle[:publish_data]["published"] == false)
      end

      def write_permitted?(collection, site, document)
        @output_bundle ||= {}
        @output_bundle[:write_collection] = collection
        @output_bundle[:write_site] = site
        @output_bundle[:write_document] = document
        return false if @output_bundle[:write_collection].nil?
        return false if @output_bundle[:write_document].nil?

        @output_bundle[:write_collection].write? &&
          @output_bundle[:write_site].publisher.publish?(@output_bundle[:write_document])
      end

      def cleaned_path_for(relative_path, extname, collection)
        @output_bundle ||= {}
        @output_bundle[:clean_relative] = relative_path.to_s
        @output_bundle[:clean_ext] = extname.to_s
        @output_bundle[:clean_collection] = collection
        path = @output_bundle[:clean_relative]
        ext = @output_bundle[:clean_ext]
        if ext.length.positive? && path.end_with?(ext)
          path = path[0..-ext.length - 1]
        end
        directory = @output_bundle[:clean_collection] && @output_bundle[:clean_collection].relative_directory
        path = path.sub(directory, "") if directory
        path.gsub(%r!\.*\z!, "")
      end

      def output_extension_for(document)
        @output_bundle ||= {}
        @output_bundle[:ext_document] = document
        @output_bundle[:ext_document].renderer.output_ext
      end

      def source_mtime_for(path)
        @output_bundle ||= {}
        @output_bundle[:mtime_path] = path
        File.mtime(@output_bundle[:mtime_path])
      end

      def draft_document?(relative_path, collection, data)
        @output_bundle ||= {}
        @output_bundle[:draft_path] = relative_path
        @output_bundle[:draft_collection] = collection
        @output_bundle[:draft_data] = data || {}
        stored = @output_bundle[:draft_data]["draft"]
        return stored unless stored.nil?

        collection_dir = @output_bundle[:draft_collection] && @output_bundle[:draft_collection].relative_directory
        @output_bundle[:draft_path].to_s.index(collection_dir.to_s).nil? &&
          @output_bundle[:draft_collection] &&
          @output_bundle[:draft_collection].label == "posts"
      end

      def merge_front_matter!(document, other, source)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:merge_document] = document
        @taxonomy_bundle[:merge_other] = other || {}
        @taxonomy_bundle[:merge_source] = source
        merge_category_list!(
          @taxonomy_bundle[:merge_document],
          @taxonomy_bundle[:merge_other]
        )
        Utils.deep_merge_hashes!(@taxonomy_bundle[:merge_document].data, @taxonomy_bundle[:merge_other])
        merge_parsed_date!(@taxonomy_bundle[:merge_document], @taxonomy_bundle[:merge_source])
        @taxonomy_bundle[:merge_document].data
      end

      def merge_category_list!(document, other)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:cat_document] = document
        @taxonomy_bundle[:cat_other] = other
        incoming = @taxonomy_bundle[:cat_other]
        return unless incoming.key?("categories") && !incoming["categories"].nil?

        incoming["categories"] = incoming["categories"].split if incoming["categories"].is_a?(String)
        current = @taxonomy_bundle[:cat_document].data["categories"]
        if current.is_a?(Array)
          incoming["categories"] = current | incoming["categories"]
        end
      end

      def merge_parsed_date!(document, source)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:date_document] = document
        @taxonomy_bundle[:date_source] = source
        data = @taxonomy_bundle[:date_document].data
        if data.key?("date")
          data["date"] = Utils.parse_date(
            data["date"].to_s,
            "Document '#{@taxonomy_bundle[:date_document].relative_path}' does not have a valid date in the #{@taxonomy_bundle[:date_source]}."
          )
        end
      end

      def fill_title_and_slug(document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:title_document] = document
        doc = @taxonomy_bundle[:title_document]
        date = slug = ext = nil
        if doc.relative_path =~ DATE_FILENAME_MATCHER
          date, slug, ext = Regexp.last_match.captures
          modify_inferred_date(doc, date)
        elsif doc.relative_path =~ DATELESS_FILENAME_MATCHER
          slug, ext = Regexp.last_match.captures
        end
        slug ||= doc.basename_without_ext
        slug.gsub!(%r!\.*\z!, "")
        doc.data["title"] ||= Utils.titleize_slug(slug)
        doc.data["slug"]  ||= slug
        doc.data["ext"]   ||= ext
      end

      def fill_categories(document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:fill_cat_document] = document
        data = @taxonomy_bundle[:fill_cat_document].data
        categories = Array(data["categories"]) + Utils.pluralized_array_from_hash(
          data, "category", "categories"
        )
        categories.map!(&:to_s)
        categories.flatten!
        categories.uniq!
        merge_front_matter!(@taxonomy_bundle[:fill_cat_document], { "categories" => categories }, "categories")
      end

      def fill_tags(document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:fill_tag_document] = document
        data = @taxonomy_bundle[:fill_tag_document].data
        tags = Utils.pluralized_array_from_hash(data, "tag", "tags")
        tags.flatten!
        merge_front_matter!(@taxonomy_bundle[:fill_tag_document], { "tags" => tags }, "tags")
      end

      def categories_from_special_dir(document, special_dir)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:special_document] = document
        @taxonomy_bundle[:special_dir] = special_dir
        doc = @taxonomy_bundle[:special_document]
        if doc.relative_path.start_with?(@taxonomy_bundle[:special_dir])
          superdirs = []
        else
          superdirs = doc.relative_path.sub(Document.superdirs_regex(@taxonomy_bundle[:special_dir]), "")
          superdirs = superdirs.split(File::SEPARATOR)
          superdirs.reject! do |c|
            c.empty? || c == @taxonomy_bundle[:special_dir] || c == doc.basename
          end
        end
        merge_front_matter!(doc, { "categories" => superdirs }, "file path")
      end

      def modify_inferred_date(document, date)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:inferred_document] = document
        @taxonomy_bundle[:inferred_date] = date
        doc = @taxonomy_bundle[:inferred_document]
        if !doc.data["date"] || doc.data["date"].to_i == doc.site.time.to_i
          merge_front_matter!(doc, { "date" => @taxonomy_bundle[:inferred_date] }, "filename")
        end
      end

      def generate_document_excerpt(document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:excerpt_document] = document
        doc = @taxonomy_bundle[:excerpt_document]
        separator = excerpt_separator_value(doc.data, doc.site)
        return unless generate_excerpt_configured?(separator)

        doc.send(:generate_excerpt)
      end

      def excerpt_separator_value(data, site)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:separator_data] = data || {}
        @taxonomy_bundle[:separator_site] = site
        (
          @taxonomy_bundle[:separator_data]["excerpt_separator"] ||
            @taxonomy_bundle[:separator_site].config["excerpt_separator"]
        ).to_s
      end

      def generate_excerpt_configured?(separator)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:configured_separator] = separator.to_s
        !@taxonomy_bundle[:configured_separator].empty?
      end

      def complete_post_data(document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:complete_document] = document
        doc = @taxonomy_bundle[:complete_document]
        fill_title_and_slug(doc)
        fill_categories(doc)
        fill_tags(doc)
        generate_document_excerpt(doc)
        doc
      end

      def next_collection_doc(collection, document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:next_collection] = collection
        @taxonomy_bundle[:next_document] = document
        docs = @taxonomy_bundle[:next_collection] && @taxonomy_bundle[:next_collection].docs
        return unless docs

        pos = docs.index { |post| post.equal?(@taxonomy_bundle[:next_document]) }
        docs[pos + 1] if pos && pos < docs.length - 1
      end

      def previous_collection_doc(collection, document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:previous_collection] = collection
        @taxonomy_bundle[:previous_document] = document
        docs = @taxonomy_bundle[:previous_collection] && @taxonomy_bundle[:previous_collection].docs
        return unless docs

        pos = docs.index { |post| post.equal?(@taxonomy_bundle[:previous_document]) }
        docs[pos - 1] if pos && pos.positive?
      end

      def processable_entry?(site, content, relative_path)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:process_site] = site
        @taxonomy_bundle[:process_content] = content
        @taxonomy_bundle[:process_path] = relative_path
        if @taxonomy_bundle[:process_content].nil?
          Jekyll.logger.debug "Skipping:", "Content in #{@taxonomy_bundle[:process_path]} is nil"
          false
        elsif !@taxonomy_bundle[:process_content].valid_encoding?
          Jekyll.logger.debug "Skipping:", "#{@taxonomy_bundle[:process_path]} is not valid UTF-8"
          false
        else
          true
        end
      end

      def publishable_entry?(site, document, relative_path)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:publish_site] = site
        @taxonomy_bundle[:publish_document] = document
        @taxonomy_bundle[:publish_path] = relative_path
        will_publish = @taxonomy_bundle[:publish_site].publisher.publish?(@taxonomy_bundle[:publish_document])
        if !will_publish && @taxonomy_bundle[:publish_site].publisher.hidden_in_the_future?(@taxonomy_bundle[:publish_document])
          Jekyll.logger.warn "Skipping:", "#{@taxonomy_bundle[:publish_path]} has a future date"
        end
        will_publish
      end

      def arrange_collection_docs(collection)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:arrange_collection] = collection
        coll = @taxonomy_bundle[:arrange_collection]
        metadata = coll.metadata || {}
        if metadata["order"].is_a?(Array)
          rearrange_docs_by_order(coll)
        elsif metadata["sort_by"].is_a?(String)
          sort_docs_by_metadata_key(coll)
        else
          coll.docs.sort!
        end
      end

      def sort_docs_by_metadata_key(collection)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:sort_collection] = collection
        coll = @taxonomy_bundle[:sort_collection]
        meta_key = coll.metadata["sort_by"]
        coll.docs.map! { |doc| [doc.data[meta_key], doc] }.sort! do |apples, olives|
          order = determine_docs_sort_order(meta_key, apples, olives)
          if order.nil? || order.zero?
            apples[-1] <=> olives[-1]
          else
            order
          end
        end.map!(&:last)
      end

      def determine_docs_sort_order(sort_key, apples, olives)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:sort_key] = sort_key
        @taxonomy_bundle[:sort_left] = apples
        @taxonomy_bundle[:sort_right] = olives
        apple_property, apple_document = @taxonomy_bundle[:sort_left]
        olive_property, olive_document = @taxonomy_bundle[:sort_right]
        if apple_property.nil? && !olive_property.nil?
          order_docs_with_warning(@taxonomy_bundle[:sort_key], apple_document, 1)
        elsif !apple_property.nil? && olive_property.nil?
          order_docs_with_warning(@taxonomy_bundle[:sort_key], olive_document, -1)
        else
          apple_property <=> olive_property
        end
      end

      def rearrange_docs_by_order(collection)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:order_collection] = collection
        coll = @taxonomy_bundle[:order_collection]
        docs_table = {}
        custom_order = {}
        coll.docs.sort.each do |doc|
          docs_table[doc.relative_path] = doc
        end
        Array(coll.metadata["order"]).each do |entry|
          custom_order[File.join(coll.relative_directory, entry)] = nil
        end
        result = Jekyll::Utils.deep_merge_hashes(custom_order, docs_table).values
        result.compact!
        coll.docs = result
      end

      def order_docs_with_warning(sort_key, document, order)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:warn_key] = sort_key
        @taxonomy_bundle[:warn_document] = document
        @taxonomy_bundle[:warn_order] = order
        Jekyll.logger.warn "Sort warning:", "'#{@taxonomy_bundle[:warn_key]}' not defined in #{@taxonomy_bundle[:warn_document].relative_path}"
        @taxonomy_bundle[:warn_order]
      end

      def resolve_document_date(data, is_draft, site, path)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:resolve_data] = data || {}
        @taxonomy_bundle[:resolve_draft] = is_draft
        @taxonomy_bundle[:resolve_site] = site
        @taxonomy_bundle[:resolve_path] = path
        current = @taxonomy_bundle[:resolve_data]["date"]
        return current unless current.nil?

        if @taxonomy_bundle[:resolve_draft]
          source_mtime_for(@taxonomy_bundle[:resolve_path])
        else
          @taxonomy_bundle[:resolve_site].time
        end
      end

      def related_document_list(document)
        @taxonomy_bundle ||= {}
        @taxonomy_bundle[:related_document] = document
        Jekyll::RelatedPosts.new(@taxonomy_bundle[:related_document]).build
      end

      def hour_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:hour_date] = date
        return "00" unless @url_bundle[:hour_date].respond_to?(:strftime)

        @url_bundle[:hour_date].strftime("%H")
      end

      def minute_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:minute_date] = date
        return "00" unless @url_bundle[:minute_date].respond_to?(:strftime)

        @url_bundle[:minute_date].strftime("%M")
      end

      def second_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:second_date] = date
        return "00" unless @url_bundle[:second_date].respond_to?(:strftime)

        @url_bundle[:second_date].strftime("%S")
      end

      def i_day_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:i_day_date] = date
        return "1" unless @url_bundle[:i_day_date].respond_to?(:strftime)

        @url_bundle[:i_day_date].strftime("%-d")
      end

      def i_month_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:i_month_date] = date
        return "1" unless @url_bundle[:i_month_date].respond_to?(:strftime)

        @url_bundle[:i_month_date].strftime("%-m")
      end

      def short_month_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:short_month_date] = date
        return "" unless @url_bundle[:short_month_date].respond_to?(:strftime)

        @url_bundle[:short_month_date].strftime("%b")
      end

      def long_month_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:long_month_date] = date
        return "" unless @url_bundle[:long_month_date].respond_to?(:strftime)

        @url_bundle[:long_month_date].strftime("%B")
      end

      def short_year_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:short_year_date] = date
        return "" unless @url_bundle[:short_year_date].respond_to?(:strftime)

        @url_bundle[:short_year_date].strftime("%y")
      end

      def slug_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:slug_document] = document
        doc = @url_bundle[:slug_document]
        Utils.slugify(doc.data["slug"]) || Utils.slugify(doc.basename_without_ext)
      end

      def pretty_title_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:pretty_document] = document
        doc = @url_bundle[:pretty_document]
        Utils.slugify(doc.data["slug"], :mode => "pretty", :cased => true) ||
          Utils.slugify(doc.basename_without_ext, :mode => "pretty", :cased => true)
      end

      def name_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:name_document] = document
        Utils.slugify(@url_bundle[:name_document].basename_without_ext)
      end

      def categories_path_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:categories_document] = document
        doc = @url_bundle[:categories_document]
        category_set = Set.new
        Array(doc.data["categories"]).each do |category|
          category_set << category.to_s.downcase
        end
        category_set.to_a.join("/")
      end

      def slugified_categories_fragment(document)
        @url_bundle ||= {}
        @url_bundle[:slug_categories_document] = document
        doc = @url_bundle[:slug_categories_document]
        Array(doc.data["categories"]).each_with_object(Set.new) do |category, set|
          set << Utils.slugify(category.to_s)
        end.to_a.join("/")
      end

      def assign_page_payload(payload, document)
        @render_bundle ||= {}
        @render_bundle[:payload] = payload
        @render_bundle[:document] = document
        @render_bundle[:payload]["page"] = @render_bundle[:document].to_liquid
        if @render_bundle[:document].respond_to?(:pager)
          @render_bundle[:payload]["paginator"] = @render_bundle[:document].pager.to_liquid
        else
          @render_bundle[:payload]["paginator"] = nil
        end
        @render_bundle[:payload]
      end

      def assign_highlighter_options(payload, converters)
        @render_bundle ||= {}
        @render_bundle[:highlight_payload] = payload
        @render_bundle[:converters] = converters
        converter = @render_bundle[:converters].first
        @render_bundle[:highlight_payload]["highlighter_prefix"] = converter.highlighter_prefix
        @render_bundle[:highlight_payload]["highlighter_suffix"] = converter.highlighter_suffix
        @render_bundle[:highlight_payload]
      end

      def invalid_layout_assignment?(document, layout, layouts)
        @render_bundle ||= {}
        @render_bundle[:layout_document] = document
        @render_bundle[:layout_object] = layout
        @render_bundle[:layout_map] = layouts || {}
        layout_exists_for?(document, @render_bundle[:layout_map])
        data = @render_bundle[:layout_document].data || {}
        return false if data["layout"].nil?
        return false unless @render_bundle[:layout_object].nil?
        return false if @render_bundle[:layout_document].class.name == "Jekyll::Excerpt"

        true
      end

      def permalink_extension_for(document)
        @render_bundle ||= {}
        @render_bundle[:permalink_document] = document
        permalink = @render_bundle[:permalink_document].permalink
        return if permalink.nil? || permalink.end_with?("/")

        ext = File.extname(permalink)
        ext unless ext.empty?
      end

      def converter_output_extension_for(document, converters)
        @render_bundle ||= {}
        @render_bundle[:conv_document] = document
        @render_bundle[:conv_list] = converters || []
        exts = collect_output_extensions(@render_bundle[:conv_document], @render_bundle[:conv_list])
        if exts.size == 1
          exts.last
        else
          exts[-2]
        end
      end

      def collect_output_extensions(document, converters)
        @render_bundle ||= {}
        @render_bundle[:ext_document] = document
        @render_bundle[:ext_converters] = converters || []
        @render_bundle[:ext_converters].map do |converter|
          converter.output_ext(@render_bundle[:ext_document].extname)
        end.tap(&:compact!)
      end

      def prepare_render_registers(site, payload)
        @render_bundle ||= {}
        @render_bundle[:register_site] = site
        @render_bundle[:register_payload] = payload
        liquid_options = @render_bundle[:register_site].config["liquid"] || {}
        {
          :registers        => {
            :site => @render_bundle[:register_site],
            :page => @render_bundle[:register_payload]["page"],
          },
          :strict_filters   => liquid_options["strict_filters"],
          :strict_variables => liquid_options["strict_variables"],
        }
      end

      def render_markup_pipeline(renderer, document, output, payload, info)
        @render_bundle ||= {}
        @render_bundle[:pipeline_renderer] = renderer
        @render_bundle[:pipeline_document] = document
        @render_bundle[:pipeline_output] = output
        @render_bundle[:pipeline_payload] = payload
        @render_bundle[:pipeline_info] = info
        doc = @render_bundle[:pipeline_document]
        engine = @render_bundle[:pipeline_renderer]
        result = @render_bundle[:pipeline_output]
        if doc.render_with_liquid?
          Jekyll.logger.debug "Rendering Liquid:", doc.relative_path
          result = engine.render_liquid(result, payload, info, doc.path)
        end
        Jekyll.logger.debug "Rendering Markup:", doc.relative_path
        result = engine.convert(result.to_s)
        doc.content = result
        Jekyll.logger.debug "Post-Convert Hooks:", doc.relative_path
        doc.trigger_hooks(:post_convert)
        result = doc.content
        if doc.place_in_layout?
          Jekyll.logger.debug "Rendering Layout:", doc.relative_path
          result = engine.place_in_layouts(result, payload, info)
        end
        result
      end

      def layout_exists_for?(document, layouts)
        @render_bundle ||= {}
        @render_bundle[:exists_document] = document
        @render_bundle[:exists_layouts] = layouts || {}
        layout_name = @render_bundle[:exists_document].data["layout"].to_s
        return true if layout_name.empty?

        @render_bundle[:exists_layouts].key?(layout_name)
      end

      def iso_week_year_fragment(date)
        @url_bundle ||= {}
        @url_bundle[:iso_year_date] = date
        return "" unless @url_bundle[:iso_year_date].respond_to?(:strftime)

        @url_bundle[:iso_year_date].strftime("%G")
      end

      def iso_week_fragment(date)
